from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(float)
# use color distance to representative ramp colors to estimate each centerline via nearest y per x
colors={'green':np.array([28,65,72]),'yellow':np.array([56,63,23]),'blue1':np.array([39,30,50]),'blue2':np.array([48,55,71]),'green2':np.array([51,64,24]),'yellow2':np.array([99,82,16])}
rois={'green':(45,90,0,18),'yellow':(75,120,14,35),'blue1':(108,170,31,52),'blue2':(110,170,65,84),'green2':(54,122,82,102),'yellow2':(75,140,112,135)}
for name,c in colors.items():
 x1,x2,y1,y2=rois[name];pts=[]
 for x in range(x1,x2):
  ys=np.arange(y1,y2);ds=np.linalg.norm(im[ys,x]-c,axis=1)
  if ds.min()<35:pts.append((x,ys[ds.argmin()],ds.min()))
 p=np.array(pts);co=np.polyfit(p[:,0],p[:,1],1);res=p[:,1]-np.polyval(co,p[:,0])
 print(name,'n',len(p),'fit',co,'res',res.std(),'samples',[(int(x),int(y)) for x,y,d in pts[::max(1,len(pts)//8)]])
PY"
